```json
{
  "root_causes": [
    {
      "service": "ts-admin-user-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-admin-user-service' AND span_name='AdminUserController.getAllUsers' GROUP BY 1,2 UNION ALL SELECT 'norm', span_name, count(*), approx_quantile(duration,0.5)/1e6, approx_quantile(duration,0.95)/1e6 FROM normal_traces WHERE service_name='ts-admin-user-service' AND span_name='AdminUserController.getAllUsers' GROUP BY 1,2",
          "claim": "AdminUserController.getAllUsers p50 rose from about 7 ms to about 1650 ms, p95 to about 1650 ms, across all calls."
        },
        {
          "kind": "trace",
          "sql": "SELECT s.service_name, s.span_name, s.attr_span_kind, s.duration/1e6 AS ms FROM abnormal_traces s WHERE s.trace_id = (SELECT trace_id FROM abnormal_traces WHERE service_name='ts-admin-user-service' AND span_name='AdminUserController.getAllUsers' LIMIT 1)",
          "claim": "In one slow trace, getAllUsers takes about 1652 ms while its only child client GET takes about 8 ms."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' src, metric, avg(value) a FROM abnormal_metrics WHERE service_name='ts-admin-user-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set','k8s.pod.filesystem.usage') GROUP BY 1,2 UNION ALL SELECT 'norm', metric, avg(value) FROM normal_metrics WHERE service_name='ts-admin-user-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set','k8s.pod.filesystem.usage') GROUP BY 1,2",
          "claim": "Pod CPU, memory and filesystem usage stay near normal levels, so the slowdown is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-admin-user-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='GET /api/v1/adminuserservice/users' GROUP BY 1,2 UNION ALL SELECT 'norm', span_name, count(*), approx_quantile(duration,0.5)/1e6 FROM normal_traces WHERE service_name='ts-ui-dashboard' AND span_name='GET /api/v1/adminuserservice/users' GROUP BY 1,2",
          "claim": "The user-facing GET /api/v1/adminuserservice/users at ts-ui-dashboard rose from about 10 ms to about 1656 ms p50."
        }
      ]
    }
  ]
}
```

